require_once __DIR__.'/includes/app.php';$cart=$_SESSION['cart']??[];if(!$cart){flash('Votre panier est vide.','error');redirect('cart.php');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['customer_name']??''));$phone=trim((string)($_POST['phone']??''));$email=trim((string)($_POST['email']??''));$address=trim((string)($_POST['address']??''));$notes=trim((string)($_POST['notes']??''));if($name===''||mb_strlen($name)>120)$errors[]='Indiquez votre nom.';if($phone===''||mb_strlen($phone)>40)$errors[]='Indiquez votre téléphone.';if($email!==''&&(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>190))$errors[]='E-mail invalide.';if($address===''||mb_strlen($address)>500)$errors[]='Indiquez votre adresse.';if(!$errors){try{$pdo=db();$pdo->beginTransaction();$total=0;$locked=[];foreach($cart as$id=>$qty){$st=$pdo->prepare('SELECT * FROM products WHERE id=? AND is_active=1 FOR UPDATE');$st->execute([(int)$id]);$pr=$st->fetch();if(!$pr||(int)$qty<1||(int)$qty>(int)$pr['stock'])throw new RuntimeException('Le stock a changé. Vérifiez votre panier.');$pr['quantity']=(int)$qty;$locked[]=$pr;$total+=(float)$pr['price']*(int)$qty;} $st=$pdo->prepare('INSERT INTO orders(customer_name,phone,email,address,notes,total,status)VALUES(?,?,?,?,?,?,?)');$st->execute([$name,$phone,$email?:null,$address,$notes?:null,$total,'pending']);$oid=(int)$pdo->lastInsertId();$item=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity)VALUES(?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($locked as$pr){$item->execute([$oid,$pr['id'],$pr['name'],$pr['price'],$pr['quantity']]);$stock->execute([$pr['quantity'],$pr['id']]);}$pdo->commit();$_SESSION['cart']=[];$_SESSION['last_order']=$oid;redirect('checkout.php?success=1');}catch(Throwable$e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$errors[]=($e instanceof RuntimeException)?$e->getMessage():'Commande impossible.';}}}
if(isset($_GET['success'])&&isset($_SESSION['last_order'])){$oid=(int)$_SESSION['last_order'];unset($_SESSION['last_order']);render_header('Commande confirmée');?><section class="container empty-state page-empty success-state"><span>✓</span><span class="eyebrow">MERCI POUR VOTRE CONFIANCE</span><h1>Votre commande est confirmée !</h1><p>Numéro de commande : <strong>#<?=$oid?></strong>. Nous vous contacterons pour confirmer la livraison.</p><a class="button button-primary" href="index.php">Retour à la boutique</a></section><?php render_footer();exit;} $ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$st=db()->prepare("SELECT * FROM products WHERE id IN ({$marks}) AND is_active=1");$st->execute($ids);$items=$st->fetchAll();$total=0;foreach($items as&i){$i['quantity']=(int)$cart[$i['id']];$total+=(float)$i['price']*$i['quantity'];}unset($i);render_header('Finaliser la commande');?>
<section class="container section checkout-page"><div class="section-heading"><div><span class="eyebrow">DERNIÈRE ÉTAPE</span><h1>Finaliser la commande</h1></div><a class="back-link" href="cart.php">← Retour au panier</a></div><?php if($errors):?><div class="notice error"><ul><?php foreach($errors as$e):?><li><?=e($e)?></li><?php endforeach?></ul></div><?php endif?><div class="cart-layout"><form method="post" class="checkout-form"><?=csrf_field()?><h2>Vos coordonnées</h2><div class="form-grid"><label>Nom complet *<input name="customer_name" required maxlength="120" value="<?=e($_POST['customer_name']??'')?>"></label><label>Téléphone *<input name="phone" required maxlength="40" value="<?=e($_POST['phone']??'')?>"></label><label class="full-field">E-mail<input type="email" name="email" value="<?=e($_POST['email']??'')?>"></label><label class="full-field">Adresse de livraison *<textarea name="address" required maxlength="500" rows="3"><?=e($_POST['address']??'')?></textarea></label><label class="full-field">Instructions<textarea name="notes" maxlength="1000" rows="3"><?=e($_POST['notes']??'')?></textarea></label></div><p class="payment-note">🔒 Paiement à la livraison.</p><button class="button button-primary button-full">Confirmer ma commande →</button></form><aside class="order-summary"><h2>Votre commande</h2><?php foreach($items as$i):?><div class="summary-row"><span><?=e($i['name'])?> × <?=$i['quantity']?></span><strong><?=money($i['price']*$i['quantity'])?></strong></div><?php endforeach?><div class="summary-total"><span>Total estimé</span><strong><?=money($total)?></strong></div></aside></div></section><?php render_footer();?>
